/**
 * Build-time helpers for the media catalogue and the face map (vite.config.ts). Nothing here ships as such:
 *
 * - `compactMediaModule` rewrites media.gen.ts (generated by tools/media, in the entry bundle) into a compact table
 *   and a few lines that rebuild the very same MEDIA object at load. Every clip repeats `/media/<id>/` and the same
 *   few codec strings, which gzip still pays for: the compact form is ~3 KiB lighter in the entry.
 * - `heroFacesModule` picks her face box in each stage clip (hero, HD hero, night) out of faces.gen.json, so the
 *   home places her face from the measured map without shipping the whole map in the entry.
 */
import type { MediaEntry } from './media.gen';

export const parseMediaSource = (src: string): Record<string, MediaEntry> =>
  JSON.parse(src.slice(src.indexOf('= {') + 2, src.lastIndexOf(';'))) as Record<string, MediaEntry>;

const CATS = ['scene', 'costume', 'prop', 'ambient', 'character'] as const;

export function compactMediaModule(src: string): string {
  const media = parseMediaSource(src);
  const types: string[] = [];
  const ty = (t: string) => { let k = types.indexOf(t); if (k < 0) { k = types.length; types.push(t); } return k; };
  const rows = Object.values(media).map((e) => {
    const base = `/media/${e.id}/`;
    const rel = (u: string) => (u.startsWith(base) ? u.slice(base.length) : u);
    return [
      e.id, CATS.indexOf(e.category), e.star ?? 0, e.ratio, rel(e.poster),
      e.posters ? e.posters.map((p) => [rel(p.src), p.width]) : 0,
      e.sources.map((s) => [rel(s.src), ty(s.type), s.width, s.height]),
      e.views ? e.views.map(rel) : 0, e.sheet ? rel(e.sheet) : 0
    ];
  });
  return `const C=${JSON.stringify(CATS)},T=${JSON.stringify(types)},R=${JSON.stringify(rows)};
export const MEDIA={};
for(const[id,c,star,ratio,p,ps,ss,vs,sh]of R){const b="/media/"+id+"/",u=(x)=>x[0]==="/"?x:b+x,e={id,category:C[c]};if(star)e.star=star;e.ratio=ratio;e.poster=u(p);e.sources=ss.map(([s,t,w,h])=>({src:u(s),type:T[t],width:w,height:h}));if(ps)e.posters=ps.map(([s,w])=>({src:u(s),width:w}));if(vs)e.views=vs.map(u);if(sh)e.sheet=u(sh);MEDIA[id]=e}
`;
}

/**
 * A-M11: the width a poster is drawn at when it covers the screen (the home stage): the full width, or wider when the
 * screen is taller than the clip (a 9:16 clip on a 390×844 phone is 56.25vh = 475px wide). The stage's <img sizes>
 * and the HTML's preload (vite.config.ts) use this same string, so the browser picks one file and fetches it once.
 */
export const coverSizes = (ratio: string): string => (ratio === '16:9' ? 'max(100vw, 177.78vh)' : 'max(100vw, 56.25vh)');

/** Her face box [left, top, right, bottom] (0–1 of the frame) in every clip the home stage may play. */
export function heroFacesModule(facesJson: string): string {
  const faces = JSON.parse(facesJson) as Record<string, number[]>;
  const pick = Object.fromEntries(Object.entries(faces).filter(([id]) => /-(herohd|hero|night)-(9x16|16x9)$/.test(id)));
  return `export const HERO_FACES=${JSON.stringify(pick)};`;
}
